// usage: bun report-links.ts [--external <failures.txt>] [--quarantine <state.json>] <failures.txt>...
// SITE_OUTCOME and EXTERNAL_OUTCOME mark a check as crashed when it failed without listing any links.
import {
  appendFileSync,
  existsSync,
  readFileSync,
  writeFileSync,
} from "node:fs";

import { reportIssue } from "./report-issue";

export type Row = { where: string; link: string; status: string };

export type Quarantine = Record<string, { since: string; status: string }>;

const DAY = 24 * 60 * 60 * 1000;

/** Reads `path:line: url: status` lines. The status keeps a code alone, and drops a network error's url tail. */
export function parseFailures(text: string): Row[] {
  return text.split("\n").flatMap((line) => {
    const match = line.match(/^(.+?): (.+?): (.*)$/);
    if (!match) {
      return [];
    }
    const [, where, link, status] = match;
    return [
      {
        where,
        link,
        status: status
          .replace(/^Rejected status code: (\d+).*/, "$1")
          .replace(/ \(.*\)$/, ""),
      },
    ];
  });
}

// A status change keeps the clock running; only a pass resets it.
export function quarantine(
  rows: readonly Row[],
  state: Quarantine,
  today: string,
): { due: Row[]; state: Quarantine } {
  const next: Quarantine = Object.fromEntries(
    rows.map((row) => [
      row.link,
      { since: state[row.link]?.since ?? today, status: row.status },
    ]),
  );
  return {
    due: rows.filter(
      (row) => Date.parse(today) - Date.parse(next[row.link].since) >= 6 * DAY,
    ),
    state: next,
  };
}

type ReportContext = {
  date: string;
  runUrl: string;
  blobUrl: string;
  crashed?: readonly string[];
  max?: number;
};

const escapeCell = (text: string) => text.replaceAll("|", "\\|");

export function formatReport(
  rows: readonly Row[],
  { date, runUrl, blobUrl, crashed = [], max = 300 }: ReportContext,
): string {
  const unique = [
    ...new Map(
      rows.map((row) => [`${row.where}: ${row.link}: ${row.status}`, row]),
    ),
  ]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([, row]) => row);
  if (unique.length === 0 && crashed.length === 0) {
    return "";
  }
  const sections = [
    `> Generated by [\`docs-links-site.yml\`](${blobUrl}/.github/workflows/docs-links-site.yml). Each weekly run replaces this description, so edits here are lost: comment instead.`,
  ];
  if (unique.length > 0) {
    sections.push(
      [
        `The weekly link check found **${unique.length} broken links** on ${date} ([run](${runUrl})).`,
        "A redirect counts as broken for metabase.com and our GitHub wikis: see `docs/util/README.md`.",
        "A link to another site is listed once it has failed two weekly runs in a row.",
      ].join("\n"),
      [
        "| Where | Link | Status |",
        "| --- | --- | --- |",
        ...unique.slice(0, max).map(({ where, link, status }) => {
          const at = where.lastIndexOf(":");
          const location = `${blobUrl}/${where.slice(0, at)}#L${where.slice(at + 1)}`;
          return `| [\`${where}\`](${location}) | ${escapeCell(link)} | ${escapeCell(status)} |`;
        }),
      ].join("\n"),
    );
    if (unique.length > max) {
      sections.push(`…and ${unique.length - max} more in the run.`);
    }
  }
  for (const check of crashed) {
    sections.push(
      `Checking ${check} failed on ${date} without listing any links. See the [run](${runUrl}).`,
    );
  }
  return sections.join("\n\n");
}

const readFailures = (file: string) =>
  existsSync(file) ? parseFailures(readFileSync(file, "utf8")) : [];

const isOtherSite = (row: Row) =>
  /^https?:\/\/(?!([\w-]+\.)*metabase\.com([/:?#]|$))/.test(row.link);

// `import.meta.main` keeps the spec, which imports the helpers above, from running the script.
if ((import.meta as ImportMeta & { main?: boolean }).main) {
  const args = process.argv.slice(2);
  const flag = (name: string) => {
    const at = args.indexOf(name);
    return at >= 0 ? args.splice(at, 2)[1] : undefined;
  };
  const externalFile = flag("--external");
  const quarantineFile = flag("--quarantine");
  const today = new Date().toISOString().slice(0, 10);

  const site = args.flatMap(readFailures);
  const external = externalFile ? readFailures(externalFile) : [];
  const siteCrashed =
    process.env.SITE_OUTCOME === "failure" && site.length === 0;
  const externalCrashed =
    process.env.EXTERNAL_OUTCOME === "failure" && external.length === 0;

  const held = external.filter(isOtherSite);
  let due = held;
  // A crashed external check saw no links, so keeping its state keeps every clock running.
  if (quarantineFile && !externalCrashed) {
    const state = existsSync(quarantineFile)
      ? // Only this script writes the file, which the workflow carries over between runs.
        (JSON.parse(readFileSync(quarantineFile, "utf8")) as Quarantine)
      : {};
    const result = quarantine(held, state, today);
    writeFileSync(quarantineFile, `${JSON.stringify(result.state, null, 2)}\n`);
    due = result.due.map((row) => ({
      ...row,
      status: `${row.status} since ${result.state[row.link].since}`,
    }));
  }

  const report = formatReport(
    [...site, ...external.filter((row) => !isOtherSite(row)), ...due],
    {
      date: today,
      runUrl: process.env.RUN_URL ?? "",
      blobUrl: process.env.BLOB_URL ?? "",
      crashed: [
        ...(siteCrashed ? ["metabase.com and GitHub wiki links"] : []),
        ...(externalCrashed ? ["links to other sites"] : []),
      ],
    },
  );
  console.log(report);
  if (process.env.GITHUB_OUTPUT) {
    appendFileSync(
      process.env.GITHUB_OUTPUT,
      `broken=${report ? "true" : "false"}\n`,
    );
  }

  await reportIssue({
    title: "metabase/metabase broken links report",
    report,
    opened: (link) =>
      `:link: The weekly link check found broken links in metabase/metabase: ${link}`,
    closed: (link) =>
      `:white_check_mark: All links in metabase/metabase pass again, closed ${link}`,
    closedComment: `All links pass as of ${process.env.RUN_URL}`,
  });
}
